const script = String.raw`
const fs = require('fs');
const ASAR = 'D:\\Users\\jjq21\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar';
const head = Buffer.alloc(16);
const fd = fs.openSync(ASAR, 'r');
fs.readSync(fd, head, 0, 16, 0);
const jsonSize = head.readUInt32LE(12);
const jbuf = Buffer.alloc(jsonSize);
fs.readSync(fd, jbuf, 0, jsonSize, 16);
const dir = JSON.parse(jbuf.toString('utf8'));
const dataStart = 16 + jsonSize;
function walk(node, prefix, out) {
 for (const k of Object.keys(node.files || {})) {
 const v = node.files[k];
 const p = prefix ? prefix + '/' + k : k;
 if (v.files) walk(v, p, out); else out.push([p, v]);
 }
}
const all = [];
walk(dir, '', all);
console.log('TOTAL', all.length);
const targets = all.filter(([p]) => p.includes('dsh-web-app') && /\.(js|mjs|cjs|css)$/.test(p));
console.log('WEBAPP_ASSETS', targets.length);
const home = 'D:\\Users\\jjq21\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar.unpacked\\_ofm_probe';
fs.mkdirSync(home, { recursive: true });
const out = [];
let n = 0;
for (const [p, v] of targets) {
 const b = Buffer.alloc(v.size);
 fs.readSync(fd, b, 0, v.size, dataStart + parseInt(v.offset, 10));
 const dest = home + '\\' + String(n++).padStart(3, '0') + '_' + p.split('/').pop();
 fs.writeFileSync(dest, b);
 out.push(dest + ' <- ' + p + ' (' + v.size + ')');
}
fs.closeSync(fd);
console.log(out.join('\n'));
`;
await tools.write({ file_path: "C:\\Users\\jjq21\\AppData\\Local\\Temp\\ofm-asar-probe.cjs", content: script });
